import{_ as i,o as e,c as l,a0 as o}from"./chunks/framework.Bmhw_dvp.js";const c=JSON.parse('{"title":"游戏机制理解（大模型阅读系统/装备/道具页后的整理）","description":"","frontmatter":{},"headers":[],"relativePath":"llm_reco/game-mechanics.md","filePath":"llm_reco/game-mechanics.md"}'),r={name:"llm_reco/game-mechanics.md"};function a(n,t,s,d,u,g){return e(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="游戏机制理解-大模型阅读系统-装备-道具页后的整理" tabindex="-1">游戏机制理解（大模型阅读系统/装备/道具页后的整理） <a class="header-anchor" href="#游戏机制理解-大模型阅读系统-装备-道具页后的整理" aria-label="Permalink to &quot;游戏机制理解（大模型阅读系统/装备/道具页后的整理）&quot;">​</a></h1><blockquote><p>来源：<code>site/zh/</code> 下已翻译的系统页（battle / getting-started / unique-effects / skills / equipment / raid-recommended）。 这是&quot;理解层&quot;，用户可在此纠正我的机制理解。</p></blockquote><h2 id="_1-战斗底层-battle-md" tabindex="-1">1. 战斗底层（battle.md） <a class="header-anchor" href="#_1-战斗底层-battle-md" aria-label="Permalink to &quot;1. 战斗底层（battle.md）&quot;">​</a></h2><ul><li><strong>体力(ST)</strong>：随时间流失，归 0 角色撤退。⇒ 体力抑制/回复（仁王纳豆、治疗、不会撤退）决定能否站场。</li><li><strong>行动速度</strong>：最重要。3 秒角色≈6 秒角色的 2 倍出手次数。装备火箭引擎(物理)/咆哮猛虎(魔法)缩短冷却。</li><li><strong>必杀充能效率</strong>：SSR≈10%，R/SR≈7.5%；低于 10% 必杀明显更慢，低于 6% 单人难以发动。超昂装备/装备补丁可提。</li><li><strong>必杀倍率（battle.md 原文表）</strong>：単体 6→9 倍（觉醒强化时）；横一列（前排1+后排2）4→6 倍；全体（最多5体，无视&quot;援护&quot;）2→4 倍。 ⇒ AoE 倍率低但覆盖多体；<strong>raid BOSS 单体不倒下</strong>，故 单体必杀倍率(9倍)在 raid 木桩上是&quot;单位时间总伤害&quot;最高的一类，全体必杀靠覆盖多体分摊，但 raid 木桩只有1体，全体必杀的&quot;多体优势&quot;在木桩上不兑现。</li><li><strong>连击（連撃）机制（battle.md 精确事实，用户重点）</strong>： <ul><li>连击率决定普通攻击时连续攻击的概率；每次连击伤害衰减 20%，下限 30%（即 80%→60%→40%→30%→30%…）。</li><li><strong>连击中「必杀充填量带来的必杀计量条增加」不发生</strong>（&quot;必杀充填量…連击中不发生&quot;）；反击、连击中追加攻击时计量条也不增加。</li><li>连击发生时行动计量条（☆）不前进，&quot;连击发生过多会使行动周期变慢，结果必杀技发动变慢&quot; → <strong>连击输出角色必杀节奏更慢、必杀伤害在总分中占比应降低</strong>（这就是用户要求的&quot;连击输出必杀倍率伤害权重降低&quot;的结构性依据）。</li><li>raid 中因敌人不倒下，连击暴击也不发生（&quot;連撃不暴击&quot;）；连击在 raid 往往偏负面，除非低连击率 FEVER 外多放1次必杀、或极度专精连击(20+连)伤害超2次必杀。</li><li>⇒ <strong>建模含义</strong>：把输出角色分为 単体/全体/連撃 三类；連撃型（高连击率）的 必杀倍率 伤害权重下调，普通攻击连击伤害权重上调（连击是其主要输出手段）。</li></ul></li><li><strong>暴击（仅团队战/raid）</strong>：raid 中赋予&quot;命中buff&quot;（攻击力提升）时，按效果量%触发暴击判定，必杀+普攻伤害 ×1.25；连击不暴击。⇒ 我方固定带攻击buff（副装B1 +30%）即稳定触发暴击，CRIT=1.25 进单角色分。</li><li><strong>FEVER（狂热）</strong>：raid 中充分培养的大半攻击者 FEVER 内可放 2 次必杀；部分有加速必杀手段的角色可能放第3次。⇒ FEVER=3 倍作为必杀伤害的常驻乘区（机制常亮）。</li><li><strong>必杀充能效率（必殺充填量）</strong>：每次普攻增加的必杀槽量；与行动速度协同极大。未强化：R/SR≈7.5%、SSR≈10%；低于10%必杀明显变慢，低于6%单人难发动。⇒ 行动速度(sec，越小越快，最快3s)与必杀充能效率(%)共同决定必杀释放频率 → 进 tempo 轴。</li><li><strong>前排/后排</strong>：近战(黄)只能前排，最多 3 前排；远程(蓝)可前/后。后排需≥2 远程才满 5 人上场。</li><li><strong>属性(太阳/月/星)</strong>：同属性攻击 1.2 倍；无石头剪刀布。阵营(战士/闪忍/神骑/魔女)用于特攻与固有效 buff。</li><li><strong>异常状态</strong>：中毒/魅惑/眩晕/咒缚。魅惑最危险（魅惑你方单位）；需免疫角色（闪忍喵子、制服喵子）或解除（六法杖塞拉菲鲁、女仆百合佩）。</li></ul><h2 id="_2-养成铁律-getting-started-md-★最重要★" tabindex="-1">2. 养成铁律（getting-started.md）★最重要★ <a class="header-anchor" href="#_2-养成铁律-getting-started-md-★最重要★" aria-label="Permalink to &quot;2. 养成铁律（getting-started.md）★最重要★&quot;">​</a></h2><ul><li><strong>满突破★5 的 R ≫ 零突破★1 的 SSR</strong>。突破(限界突破)拉到★5 是性价比核心。</li><li>新手首要目标：角色兑换所换往期 R，★5 突破。官方点名新手核心：魔女雫(顶级治疗)、节拍偶像·玉木、节拍偶像·明惠、万圣节绮蕾、魔女哈皮。</li><li><strong>助战(借用)是最强工具</strong>：借高阶单位，无视属性限制。</li><li>装备优先级：火箭引擎/咆哮猛虎(速度) &gt; 仁王纳豆(体力抑制) &gt; 冲击腰带(攻魔) &gt; 超级钻头(必杀槽) &gt; 斗志十姐妹；超昂金(按阵营攻击)、圣剑科斯莫斯(超昂祭全能属性)。</li></ul><h2 id="_3-固有效果-unique-effects-md-关键模式" tabindex="-1">3. 固有效果(unique-effects.md) 关键模式 <a class="header-anchor" href="#_3-固有效果-unique-effects-md-关键模式" aria-label="Permalink to &quot;3. 固有效果(unique-effects.md) 关键模式&quot;">​</a></h2><ul><li><strong>阵营 buff</strong>：艾斯卡蕾雅(战士+)、闪忍遥(闪忍+)、神骑艾克希尔(神骑+)、魔女雫(魔女+)——同阵营编队大幅增伤。</li><li><strong>不会撤退</strong>：体力 0 不撤退（节拍音速·阿喀琉斯、婚纱遥·逆转形态、盛夏遥、R真百合/FM77/玲奈/弗洛雷鲁、超昂闪忍知留香、盛夏风香）——站场输出的标志。</li><li><strong>魅惑/异常免疫</strong>：闪忍喵子&quot;在场期间友军效果无效&quot;(=免疫敌方魅惑等减益)；制服喵子全异常免疫；闪忍节喵(R)束缚免疫；和装塞拉菲鲁束缚免疫；婚纱·库鲁鲁眩晕免疫。</li><li><strong>体力抑制/回复</strong>：超昂·玛瑙、超昂闪忍成香、万圣节艾克希尔、女郎蜘蛛初音、八爪妖蛊初音等自带体力流失减缓。</li><li><strong>速度/充能</strong>：闪忍彩香(R)300% 速度辅助；神骑参宿四(R)全队充能；妹妹1024 顶尖充能+速度。</li></ul><h2 id="_4-装备-equipment-md-核心" tabindex="-1">4. 装备(equipment.md) 核心 <a class="header-anchor" href="#_4-装备-equipment-md-核心" aria-label="Permalink to &quot;4. 装备(equipment.md) 核心&quot;">​</a></h2><ul><li>主+副共 6 格；副装备栏靠强化点数扩（无★数限制）。</li><li>速度系(火箭/猛虎,带★不叠加)、体力抑制(仁王纳豆,带★)、攻魔(冲击腰带/腰带逸品)、必杀槽(超级钻头/钻头逸品)、连击(连击纳豆—巴比伦尼尔专属优先)。</li><li>超昂金：按持有[战士/闪忍/神骑/魔女]人数提升攻/魔/防御/体力——阵容不齐则无用。</li><li>圣剑科斯莫斯：超昂祭角色拥有全部属性/特殊——妮露等核心队必备。</li><li>消耗品：甜心打火机(战斗不能全回复,讨伐战珍贵)、海马栖所(损坏加突破点)、眩晕帽(防眩晕)。</li></ul><h2 id="_5-终盘内容-raid-recommended-md-官方讨伐战强度榜" tabindex="-1">5. 终盘内容(raid-recommended.md = 官方讨伐战强度榜) <a class="header-anchor" href="#_5-终盘内容-raid-recommended-md-官方讨伐战强度榜" aria-label="Permalink to &quot;5. 终盘内容(raid-recommended.md = 官方讨伐战强度榜)&quot;">​</a></h2><ul><li>三类定位：<strong>输出(DPS)</strong> / <strong>增益减益辅助(支援)</strong> / <strong>治疗</strong>。</li><li>官方 ★★★ 输出：巴比伦·尼尔、情人节莉可丽丝、节拍风暴·叶月、王权超昂神骑尤莉艾尔、超昂闪忍知留香、超昂·玛瑙…</li><li>官方 ★★★ 辅助：妹妹1024、超昂阿梅兹·幻梦、正月锁、神骑参宿四、超昂蓝宝石·月升、盛夏风香、圣诞布罗库米艾尔、情人节彩香、巴比伦·诺诺诺…</li><li>官方 ★★★ 治疗：节拍议长·希拉、神骑雷布艾尔、正月成香、超昂托帕兹·秘境、制服喵子…</li><li>榜单偏硬核冲分（百亿伤害）；新手应看&quot;配队范例页&quot;而非此榜。⇒ 我的推荐会兼顾两者。</li></ul>',12)])])}const q=i(r,[["render",a]]);export{c as __pageData,q as default};
